import{_ as t,o as l,c as o,a2 as a}from"./chunks/framework.BUwdTBzS.js";const u=JSON.parse('{"title":"按需-更新日志编写规范","description":"更新日志（changelog）条目的编写规范（概括式、同源合并、破坏性变更保留必要信息）。撰写或修订更新日志时加载。","frontmatter":{"title":"按需-更新日志编写规范","description":"更新日志（changelog）条目的编写规范（概括式、同源合并、破坏性变更保留必要信息）。撰写或修订更新日志时加载。"},"headers":[],"relativePath":"rules/按需-更新日志编写规范.md","filePath":"rules/按需-更新日志编写规范.md","lastUpdated":null}'),i={name:"rules/按需-更新日志编写规范.md"};function d(r,e,c,n,h,s){return l(),o("div",null,[...e[0]||(e[0]=[a('<blockquote><p>📄 本页由源文件 <code>rules/按需-更新日志编写规范.mdc</code> 自动投影生成（单一权威源）。请勿直接编辑本页。</p></blockquote><h1 id="按需-更新日志编写规范" tabindex="-1">按需-更新日志编写规范 <a class="header-anchor" href="#按需-更新日志编写规范" aria-label="Permalink to &quot;按需-更新日志编写规范&quot;">​</a></h1><blockquote><p>触发时机：撰写或修订项目 <code>changelog.md</code>（或同类版本更新说明）时。 核心：日志面向<strong>使用者</strong>，只回答「哪个组件、发生了什么、我要不要动代码」。</p></blockquote><hr><h2 id="_1-描述方式-概括式" tabindex="-1">1. 描述方式：概括式 <a class="header-anchor" href="#_1-描述方式-概括式" aria-label="Permalink to &quot;1. 描述方式：概括式&quot;">​</a></h2><ul><li><strong>一条一句话</strong>，只写「改了什么 + 影响」；根因、算法、实现手段不写进日志</li><li>❌ <code>定位尺寸改用 offsetWidth / offsetHeight，因为 transform 会让 getBoundingClientRect 返回缩放后的视觉尺寸</code></li><li>✅ <code>修复缩放动画期间位置错位</code></li><li>根因、取舍与实现细节归 commit message / PR 描述</li></ul><h2 id="_2-合并同源条目" tabindex="-1">2. 合并同源条目 <a class="header-anchor" href="#_2-合并同源条目" aria-label="Permalink to &quot;2. 合并同源条目&quot;">​</a></h2><ul><li>同一组件、同一工具函数族的多个改动 → 合并为一条</li><li>❌ Tooltip 定位一条 + Tooltip 交互一条</li><li>✅ Tooltip 定位与交互合并为一条</li><li>无信息量的兜底条目（如「组件库及文档代码优化」）不写</li></ul><h2 id="_3-保留必要信息-不得过度概括" tabindex="-1">3. 保留必要信息（不得过度概括） <a class="header-anchor" href="#_3-保留必要信息-不得过度概括" aria-label="Permalink to &quot;3. 保留必要信息（不得过度概括）&quot;">​</a></h2><p>以下必须写清，压缩到看不出影响即不合格：</p><table tabindex="0"><thead><tr><th>场景</th><th>要求</th></tr></thead><tbody><tr><td>破坏性变更</td><td>保留 <code>⚠️ **破坏性变更**</code> 前缀，写明「移除了什么 / 改用什么」</td></tr><tr><td>默认值变化</td><td>写明旧值 → 新值</td></tr><tr><td>需用户改代码</td><td>写明替代写法</td></tr></tbody></table><h2 id="_4-格式约定" tabindex="-1">4. 格式约定 <a class="header-anchor" href="#_4-格式约定" aria-label="Permalink to &quot;4. 格式约定&quot;">​</a></h2><ul><li>每条以动词开头：<code>新增</code> / <code>优化</code> / <code>增强</code> / <code>修复</code> / <code>重构</code></li><li>组件与工具函数名用 Markdown 链接指向文档，如 <code>[文字提示 Tooltip](/guide/components/tooltip.html)</code></li><li>属性名、API、全局对象等用行内代码包裹</li><li>单版本条目建议 ≤ 8 条</li></ul><h2 id="_5-版本与历史" tabindex="-1">5. 版本与历史 <a class="header-anchor" href="#_5-版本与历史" aria-label="Permalink to &quot;5. 版本与历史&quot;">​</a></h2><ul><li>已发布版本的历史条目<strong>默认不回改</strong>，用户明确要求时才回改</li><li>新版本严格按本规范撰写，不因历史风格而妥协</li></ul><h2 id="_6-自检清单" tabindex="-1">6. 自检清单 <a class="header-anchor" href="#_6-自检清单" aria-label="Permalink to &quot;6. 自检清单&quot;">​</a></h2><ul><li>[ ] 每条能否一句话说清「改了什么 + 影响」？</li><li>[ ] 同组件 / 同工具函数族的条目是否已合并？</li><li>[ ] 破坏性变更、默认值变化是否写明替代用法？</li><li>[ ] 是否残留根因、算法、内部函数名等实现细节？</li><li>[ ] 无信息量的条目是否已删除？</li><li>[ ] 单版本条目数是否 ≤ 8？</li></ul>',17)])])}const p=t(i,[["render",d]]);export{u as __pageData,p as default};
